def classify(value: int) -> str:
    """if / elif / else 阶梯 + 三元表达式。"""
    if value < 0:
        label = "negative"
    elif value == 0:
        label = "zero"
    elif value < 10:
        label = "small"
    else:
        label = "large"
    parity = "even" if value % 2 == 0 else "odd"
    return f"{label}/{parity}"

