def risky(text) -> str:
    """try / except / else / finally。"""
    try:
        result = text.strip()
    except AttributeError as error:
        result = str(error)
    except (TypeError, ValueError):
        result = ""
    else:
        result = result or "empty"
    finally:
        done = True
    return result

