class Registry:
    """演示内建与自定义装饰器的类。"""

    _created = 0

    def __init__(self, name: str) -> None:
        self.name = name
        Registry._created += 1

    @property
    def display_name(self) -> str:
        """展示用的大写名称。"""
        return self.name.upper()

    @display_name.setter
    def display_name(self, value: str) -> None:
        self.name = value.lower()

    @staticmethod
    def created_count() -> int:
        """已创建的实例数。"""
        return Registry._created

    @classmethod
    def reset(cls) -> None:
        """重置实例计数。"""
        cls._created = 0

